{
  "incident": {
    "component": "mongodb",
    "category": "disk_pressure",
    "status": "firing",
    "summary": "The primary MongoDB instance is critically low on disk space with an estimated 2 hours of runway."
  },
  "assessment": {
    "urgency": "critical",
    "rationale": "The computed Time-To-Exhaustion is 2.0 hours, which meets the critical threshold (TTE <= 2h)."
  },
  "facts": [
    "filesystem_size_bytes is 429496729600.0",
    "filesystem_available_bytes is 6442450944.0",
    "growth_rate_bytes_per_hour is 3221225472.0",
    "replica_set_role is primary",
    "label.alertname is MongoDBDiskSpaceLow",
    "label.instance is mongo-prod-01:9216",
    "label.severity is warning"
  ],
  "missing_context": [
    {
      "item": "user_impact",
      "why": "We do not know if customers are currently experiencing issues.",
      "how_to_check": "Check SLO dashboards for latency/error rates of services consuming mongo-prod-01."
    },
    {
      "item": "recent_changes",
      "why": "We lack context on recent deployments or configuration changes.",
      "how_to_check": "Check CI/CD history and change calendar for the last 24 hours."
    },
    {
      "item": "replication_lag_seconds",
      "why": "We need to know the health of the replica set beyond just the primary's disk space.",
      "how_to_check": "Run 'rs.status()' on the primary."
    },
    {
      "item": "replica_set_healthy_members",
      "why": "We need to confirm if the set can survive a failure of this node.",
      "how_to_check": "Run 'rs.status()' on the primary."
    }
  ],
  "immediate_actions": [
    {
      "action": "Identify and throttle/pause the noisy writer process (e.g., batch import, migration job) writing to the database.",
      "purpose": "Reduce the rate of disk consumption to buy time.",
      "conditions": "TTE is less than 4 hours.",
      "expected_effect": "Slow down the growth rate, increasing TTE.",
      "risks": "If the noisy writer is critical, pausing it causes functional degradation. Rollback: Resume the process.",
      "requires_approval": true,
      "verify": "Monitor `growth_rate_bytes_per_hour` after throttling.",
      "rule_ids": [
        "global.harm.001"
      ]
    },
    {
      "action": "Check disk usage on all members of the replica set.",
      "purpose": "Determine if the issue is localized or systemic.",
      "conditions": "Before taking any action on the primary.",
      "expected_effect": "Confirm if other members are also running low on disk.",
      "risks": "No direct risk, but may lead to unnecessary actions if the issue is localized.",
      "requires_approval": false,
      "verify": "Query disk metrics for all nodes in the set.",
      "rule_ids": [
        "mongo.storage.003"
      ]
    }
  ],
  "investigation_steps": [
    {
      "step": "Check for recent changes that might correlate with the start of the disk pressure.",
      "hypothesis": "A recent deployment or configuration change introduced excessive logging or data volume.",
      "how_to_check": "Review Git history and deployment logs from the last 48 hours."
    },
    {
      "step": "Examine MongoDB statistics to find the largest consumers of space.",
      "hypothesis": "A specific collection or index is growing disproportionately.",
      "how_to_check": "Run 'db.collection.stats()' and 'db.stats()' to sort by storageSize."
    },
    {
      "step": "Inspect the filesystem structure for large log files or diagnostic data.",
      "hypothesis": "Excessive logging or diagnostic data is consuming space outside of managed collections.",
      "how_to_check": "Run 'du -sh /var/lib/mongodb/*' and 'du -sh /var/log/mongodb/'."
    }
  ],
  "root_cause_hypotheses": [
    "A runaway write process (e.g., an application bug or a background job) is generating data faster than expected.",
    "A new index or feature has been deployed that is significantly larger than previous versions.",
    "Log rotation has failed, causing log files to consume excessive disk space."
  ],
  "dangerous_operations": [
    {
      "operation": "drop collection/database",
      "why_dangerous": "This is irreversible without a verified backup and owner sign-off, and it is not a safe emergency fix.",
      "rule_id": "mongo.storage.006"
    }
  ],
  "applied_expert_rules": [
    "global.triage.001",
    "global.harm.001",
    "mongo.storage.003"
  ],
  "incident_update": "🔥 CRITICAL: MongoDB disk space is critically low (TTE ~2h) on primary mongo-prod-01. Immediate action is to throttle the noisy writer. We are checking other members for systemic issues. Next step: Investigate growth source via db.stats()."
}
